  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (544::BIGINT, 'Es un profesor excelente, hace que de verdad te den ganas de aprender y sus trabajos son divertidos. Los quices y exámenes son algo complicados si no entiendes bien la materia, pero hace todo lo posible por qué pases. Si le pones ganas y atención a las clases pasas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2026-07-03T00:00:00+00:00'::TIMESTAMPTZ, '0ba656fd78bc0b73b5ef3a92e8210c40f8b28be725effa8472842cfb460f2f28'::TEXT, ARRAY[1857]::BIGINT[]),
    (544::BIGINT, 'El mejor profe de química que he tenido de verdad. Hace el curso suuper llevadero, es demasiado cómico, los trabajos son entretenidos y acorde a la carrera, da chocolates en los exámenes, deja dinámicas entretenidas, la verdad que para no pasar el curso hay que ser muy pero muy vago, mi papá fr'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2026-07-03T00:00:00+00:00'::TIMESTAMPTZ, '719f148a4bfe6c2c006630731d02bba9831cce3fabcf6b6b14143fb24269f8b5'::TEXT, ARRAY[1857]::BIGINT[]),
    (544::BIGINT, 'Un profesor increíble, sus explicaciones, todo el laboratorio fue un gran aprendizaje, si tienen el chance de llevar con él no lo desaproveche, gran profe y gran persona, siempre dispuesto a ayudar, aclarar dudas, gracias por tanto profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Aspectos de calificación claros']::TEXT[], '2026-07-03T00:00:00+00:00'::TIMESTAMPTZ, 'e4d185cd22ddcfa783d8ae1a05aa1abd767b66145222a0b12818b2aec8d3d483'::TEXT, ARRAY[2738]::BIGINT[]),
    (544::BIGINT, 'Muy buen profe, sus precentaciones son muy completas y sus actividades hacen que no te distraigas mucho en la clase, sus examenes son algo dificiles pero vale totalmente la pena'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-12T00:00:00+00:00'::TIMESTAMPTZ, '83228f160375d2092429b7b5ad363fc9b1f3493899ab02d24e6b9c6781ff80d7'::TEXT, ARRAY[1857]::BIGINT[]),
    (544::BIGINT, 'Buen profesor, da una explicación antes de la práctica y responde dudas durante la práctica. A veces, él es medio complicado durante el lab y se queda sentado viendo el celular, pero sí responde las dudas que usted tenga mientras hace la práctica. Lo quices son complicados y reportes son más largos.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2025-07-04T00:00:00+00:00'::TIMESTAMPTZ, '5a908ca08d5dafc0316ff831c62929c6d00ddcecf4fcc7cee418a9c05fa3172f'::TEXT, ARRAY[2738]::BIGINT[]),
    (544::BIGINT, 'Está bien. Lástima que el curso abarque tanto contenido con poco tiempo. Hace exámenes fáciles realmente, si se alcanza a estudiar bien.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico']::TEXT[], '2025-07-01T00:00:00+00:00'::TIMESTAMPTZ, 'e926d1d67d47b6e69eef608c7501045694d0cbe7b528b8983b8a995dd0cf1f8b'::TEXT, ARRAY[3180, 3178]::BIGINT[]),
    (544::BIGINT, 'El curso de orgánica tiene su nivel de dificultad, pero llevando la materia al día, asistiendo a clases y con este profe hay muchísimas posibilidades de pasar.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-22T00:00:00+00:00'::TIMESTAMPTZ, '2ed290c74ea77a608ced9859d876858e5f74e13f23e260bd6f44f26831a70957'::TEXT, ARRAY[3180, 3178]::BIGINT[]),
    (544::BIGINT, 'Es un excelente profesor, es demasiado gracioso y explica la materia de una manera increíble, super recomendado para cualquier curso, ayuda con quices extra (hay que estudiar para los quices, son difíciles), pero sin duda es una excelente opción'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'ee8a15b00cd44fda80fabacfff451ddbb6ce26b3e4a72912f24e06bb49062ba5'::TEXT, ARRAY[2738]::BIGINT[]),
    (544::BIGINT, 'El curso como tal es bastante denso, pero el profe logra que las clases se pasen rápido, siempre hay un ambiente muy seguro y ameno, hace quices extra para descartar los que tengan mala nota y ayuda muchísimo con evaluaciones extra, muy recomendado.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Da crédito extra']::TEXT[], '2024-06-08T00:00:00+00:00'::TIMESTAMPTZ, '666f08289e0de5759a03c8ee48d2e2d25449df47bbfb797032109d20bd780e40'::TEXT, ARRAY[3180, 3178]::BIGINT[]),
    (544::BIGINT, 'El profe ayuda a quienes se esfuerzan, sus clases son divertidas, vuelve a repasar si los estudiantes preguntan, una muy calidad de profesor'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2024-04-23T00:00:00+00:00'::TIMESTAMPTZ, 'f441c64c386142ca7fee29fb55437e8b705dceb2e2d29c2feee7868c0bab8a93'::TEXT, ARRAY[614, 573]::BIGINT[]),
    (544::BIGINT, 'El curso es ya bastante dificil, pero el profe es muy cómico y le gusta llevarse bien y conocer a sus estudiantes. Hace varios quices extras, para ayudar a reponer los quices más bajos, en los exámenes permite utilizar apuntes. Les recomiendo siempre estar al día para que no se les acumule materia.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2023-12-01T00:00:00+00:00'::TIMESTAMPTZ, 'fbd2e1a45a2ff684e441439f79bd7c64069832a467950cf631cfc45cdb14c24d'::TEXT, ARRAY[3180, 3178]::BIGINT[]),
    (544::BIGINT, 'Un profesor excelente, es demasiado bueno como profesional y como persona, hay que ponerle, pero el profe siempre trata de hacer que la materia sea bonita y no tan pesada, sus clases no son aburridas. super recomendado'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-25T00:00:00+00:00'::TIMESTAMPTZ, '88b6cec6fe34404b5cd4f94dba17e2426d4dd49c0b54f735afdf44a224e32240'::TEXT, ARRAY[3180, 3178]::BIGINT[]),
    (544::BIGINT, 'Quizás, el mejor profe de la U, además de ser un excelente profesor, es una teja de persona, en mi caso lleve las químicas con él y aunque son cursillos un toque tediosos, él siempre estuvo pendiente ayudando en lo que uno necesitara.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2023-11-23T00:00:00+00:00'::TIMESTAMPTZ, 'fae22a6befa355d10b035ba922cab43d8e358fb12b338927a91f30bda67022e3'::TEXT, ARRAY[613, 614, 1857, 2738, 3180, 3178]::BIGINT[]),
    (544::BIGINT, 'un chuzo de profe y de persona. se da demasiado a querer sin perder la autoridad. se apunta mucho a las actividades de inclusión LGBTIQ+ y hasta ahi muestra su carisma. lo quiero mucho profe grax x todo'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Tomaría su clase nuevamente']::TEXT[], '2023-07-21T00:00:00+00:00'::TIMESTAMPTZ, '017bf2d97a29dc60a3e7bc144271b86026ab8e6146e5f0375c3f1060b73bd192'::TEXT, ARRAY[2738]::BIGINT[]),
    (544::BIGINT, 'El profe es muy bueno. Definitivamente es la mejor opción en cuanto a los laboratorios de orgánica, no por facilidad, pero por complemento a la materia y por las clases llevaderas. Suele calificar un poco duro, pero eso prepara para el examen final, que es muy complicado (mismo para todos los GR).'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, '38b2e5390a3ebaf7873318c7ac5a812f4619550d3d6d179d1cb2f4a632778b69'::TEXT, ARRAY[2738]::BIGINT[]),
    (544::BIGINT, 'Un 10/10 de profe. El curso tiene un montón de materia y él logra volverlo interesante. Se nota que le gusta ser profe y hace que las clases sean dinámicas y dé gusto estar ahí.} Super recomendado'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, '01ae81fe4b1d1fce1b0cdd2591eea49afcb094f9895335903280521c2fdc3452'::TEXT, ARRAY[1857]::BIGINT[]),
    (544::BIGINT, 'Muy buen profesor, bastante gracioso y explica muy bien las clases.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2022-11-03T00:00:00+00:00'::TIMESTAMPTZ, 'd250093cd8b92a683f30efd6b646f9f38e76e73753da76c7b53ac9f8df0e6c46'::TEXT, ARRAY[614]::BIGINT[]),
    (544::BIGINT, 'se mete demasiado en organica, ojala se limitara a que uno pudiera entender los conceptos de quimica2 y poder pasar los examenes. Demasiados quices'::TEXT, 2.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-10-06T00:00:00+00:00'::TIMESTAMPTZ, '4525b20b2de948b326d42a1b9529d59b28647b052adf3bb4e475c9d419a3c4fe'::TEXT, ARRAY[614]::BIGINT[]),
    (544::BIGINT, 'Es un excelente profe, hace bastantes quices (para escoger los mejores), le importa bastante si uno aprende y se nota que quiere que los estudiantes pasen el curso (da puntos extra).'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2022-08-01T00:00:00+00:00'::TIMESTAMPTZ, '91908afe07f603d8c7ceefa5d373cc9e04a3f3d4fa9ae8d86ad7ba7da3060f01'::TEXT, ARRAY[568, 573]::BIGINT[]),
    (544::BIGINT, 'El profe es bastante bueno como persona y profesional, es muy cómico pero exigente y serio cuando debe serlo. Lo peor del curso son los quices, fueron muy difíciles sin embargo se pasa bien el curso. Matricule sin miedo.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Clases excelentes']::TEXT[], '2022-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'a3d5aa0c8d5c2ae89b4693c6aa34f8600e0d7f12a86caae497806fc48fe52d81'::TEXT, ARRAY[2738]::BIGINT[]),
    (544::BIGINT, 'Matriculen con el!! Es una excelente persona, siempre esta dispuesto a ayudar a los estudiantes y es muy respetuoso. Ademas con las pruebas cortas evalua bastante suave y pone puntos extra, el quiere que la gente pase el curso.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2022-06-11T00:00:00+00:00'::TIMESTAMPTZ, '8b428a9f75b9f4f98aef8e06cbf0e6efa1ef4c2c8c9c2d37154469c21665db7f'::TEXT, ARRAY[568, 573]::BIGINT[]),
    (544::BIGINT, 'Es un muy buen profe, bastante amable, siempre dispuesto a resolver dudas de los estudiantes. Sin duda volvería tomar su clase.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Brinda apoyo']::TEXT[], '2022-06-03T00:00:00+00:00'::TIMESTAMPTZ, 'd8eff68252c834a880f96f50b5474e80d96006d418380bbbbb309322ec973399'::TEXT, ARRAY[568]::BIGINT[]),
    (544::BIGINT, 'Es un super profe. A pesar de ser un curso de teoría se siente cero pesado por como el profe da la clase. Explica súper bien y no tiene problemas aclarando la misma duda x cantidad de veces. El profe realmente esta interesado en que usted aprenda y pase el curso'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2022-05-08T00:00:00+00:00'::TIMESTAMPTZ, 'c8759497f1226cbbe7f26c8e2d9171151d309f1e3018d6e659f9d1cac3784a37'::TEXT, ARRAY[568]::BIGINT[]),
    (544::BIGINT, 'Es super buen profe, explica muy bien y es divertido, a el usted le puede expresar todas las dudas que tenga y si se pone atención se pasa fácil. Para quimica 2 matricularía con el otra vez'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-04-03T00:00:00+00:00'::TIMESTAMPTZ, '24b50574376cc19435390885dad3fe08adb3d69bf1eb7e16476b9db633b9aba3'::TEXT, ARRAY[568]::BIGINT[]),
    (544::BIGINT, 'Es un profe muy amable, explica bastante bien y no le importa las veces que uno pregunte algo, siempre tiene la amabilidad para explicarlo, las clases son largas pero se aprende si uno pone atención y apuntes. Si uno participa se le facilita entender'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-12T00:00:00+00:00'::TIMESTAMPTZ, 'e25d4e2d83c90614fba971393a7ea4744a75ff302de4806dafa1844dc0eb2fc4'::TEXT, ARRAY[614]::BIGINT[]),
    (544::BIGINT, 'Clases cortas, pero aburridas: básicamente es ver el video del lab. Hace quices antes de comenzar la clase, por lo que hay que asistir. Solo califica 6/12 informes y los califica algo rudo. El profe es agradable y cae bien, es fácil.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Muchas tareas']::TEXT[], '2021-07-12T00:00:00+00:00'::TIMESTAMPTZ, '4beae12eb7960e519d66efe2b31a5cc7e2df4feb4c3021997d5a4f5219788b4e'::TEXT, ARRAY[567]::BIGINT[]),
    (544::BIGINT, 'Es buen profe, pero las clases son un poquito aburridas . Usa salas en Teams. En general se puede matricular con él.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2021-06-22T00:00:00+00:00'::TIMESTAMPTZ, 'f1696c1ed08bc6b998b64b758c3dafc9f3f5091f9d4d8fdbdf4e90d513fd260e'::TEXT, ARRAY[567]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
